mapper.select:
SELECT INSTITUTION_ID
  FROM INSTITUTIONS
 WHERE NAME_KO = #{nameKo}

mapper.update:
UPDATE INSTITUTIONS SET REGION_CODE = COALESCE(#{row.regionCode,jdbcType=VARCHAR}, REGION_CODE), TYPE = COALESCE(#{row.type,jdbcType=VARCHAR}, TYPE), TERM = COALESCE(#{row.term,jdbcType=DECIMAL}, TERM), LAST_BID = COALESCE(#{row.lastBid,jdbcType=VARCHAR}, LAST_BID),
CONTRACT_END_CONFIRMED = 0, CONTRACT_END_SRC_URL = NULL, CONTRACT_END_SRC_NO = NULL,
CONTRACT_END = COALESCE(#{row.contractEnd,jdbcType=VARCHAR}, CONTRACT_END) WHERE INSTITUTION_ID = #{institutionId}

UPDATE INSTITUTIONS
REGION_CODE = #{upd.regionCode,jdbcType=VARCHAR}, TYPE = #{upd.type,jdbcType=VARCHAR}, CONTRACT_END = #{upd.contractEnd,jdbcType=VARCHAR}, LAST_BID = #{upd.lastBid,jdbcType=VARCHAR}, TERM = #{upd.term,jdbcType=DECIMAL}, CONTRACT_END_CONFIRMED = #{upd.contractEndConfirmedInt,jdbcType=NUMERIC}, CONTRACT_END_SRC_URL = #{upd.contractEndSrcUrl,jdbcType=VARCHAR}, CONTRACT_END_SRC_NO = #{upd.contractEndSrcNo,jdbcType=VARCHAR}, OP_STATUS = #{upd.opStatus,jdbcType=VARCHAR}, OPEN_DATE = #{upd.openDate,jdbcType=VARCHAR}, OP_SRC_URL = #{upd.opSrcUrl,jdbcType=VARCHAR}, OP_SRC_NO = #{upd.opSrcNo,jdbcType=VARCHAR},
WHERE INSTITUTION_ID = #{institutionId}

UPDATE INSTITUTIONS
   SET GIGANLIST_DIR = #{giganlistDir,jdbcType=VARCHAR}
 WHERE INSTITUTION_ID = #{institutionId}

UPDATE INSTITUTIONS
   SET RFP_PATH = #{rfpPath,jdbcType=VARCHAR}
 WHERE INSTITUTION_ID = #{institutionId}

UPDATE INSTITUTIONS
   SET PPTX_PATH = #{pptxPath,jdbcType=VARCHAR}
 WHERE INSTITUTION_ID = #{institutionId}
